# Generated by Cursor (plan: fix missing Latin letter Condé Nast)
"""Scan for words containing replacement character U+FFFD; fix known mappings (e.g. Condé)."""

import re

REPLACEMENT_CHAR = "\ufffd"
WORD_WITH_FFFD_RE = re.compile(r"\b([\w\uFFFD]+)\b")

# Allowlist: (pattern, replacement). Edited by Cursor (plan).
REPLACEMENT_FIX_MAP: list[tuple[str, str]] = [
    ("Cond\ufffd Nast", "Condé Nast"),
    ("Cond\ufffd", "Condé"),
]


def get_replacement_char_fix(span: str) -> str | None:
    """Return fixed string if span matches a known pattern; else None."""
    for pattern, replacement in REPLACEMENT_FIX_MAP:
        if span == pattern:
            return replacement
    return None


def scan_turn_replacement_char_fix(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Emit (replacement_char_fix, start_index, span, path_str) for tokens containing U+FFFD that we can fix."""
    result: list[tuple[str, int, str, str]] = []
    for m in WORD_WITH_FFFD_RE.finditer(text):
        token = m.group(1)
        if REPLACEMENT_CHAR not in token:
            continue
        # Prefer "Cond\uFFFD Nast" span when next word is "Nast"
        span = token
        if token == "Cond" + REPLACEMENT_CHAR:
            end = m.end()
            if end <= len(text) and text[end : end + 1].isspace():
                rest = text[end:].lstrip()
                if rest.startswith("Nast"):
                    span = token + " Nast"
        if get_replacement_char_fix(span) is not None:
            result.append(("replacement_char_fix", m.start(), span, path_str))
    return result
